/* This file contains some compile-time configuration options for MS Windows
 * systems when building using MSVC.
 * Change the values below if you want anything other than the defaults.
 * For *nix systems, config_unix.h is used, which is generated by build.sh
 * from src/config_unix.h.in.
 * When building on MS Windows using build.sh (MinGW, Cygwin),
 * config_win.h is generated from src/config_win.h.in.
 */

#pragma once
#ifndef UQM_CONFIG_VC6_H
#define UQM_CONFIG_VC6_H

#include "core/stl/stl.h"

/* Directory where the UQM game data is located */
inline constexpr uqgsl::czstring Contentdir {"./content/"};

/* Directory where game data will be stored */
inline constexpr uqgsl::czstring Userdir {"~/.uqm-megamodern/"};

/* Directory where config files will be stored */
inline constexpr auto Configdir {Userdir};

#ifdef _WIN32
#define UQM_CONFIG_DIR_VAR "%UQM_CONFIG_DIR%"
#else
#define UQM_CONFIG_DIR_VAR "${UQM_CONFIG_DIR}"
#endif

/* Directory where supermelee teams will be stored */
inline constexpr uqgsl::czstring Meleedir {UQM_CONFIG_DIR_VAR "/teams/"};

/* Directory where save games will be stored */
inline constexpr uqgsl::czstring Savedir {UQM_CONFIG_DIR_VAR "/save/"};

/* Directory where screenshots will be stored */
inline constexpr uqgsl::czstring Scrshotdir {UQM_CONFIG_DIR_VAR "/screenshots/"};

#undef UQM_CONFIG_DIR_VAR

#ifdef _WIN32
/* Defined if your system has stricmp of its own */
#define HAVE_STRICMP
#else
#define HAVE_READDIR_R
#define HAVE_SETENV
// Not using "HAVE_STRCASECMP" as that conflicts with SDL.
#define HAVE_STRCASECMP_UQM
#endif

/* Defined if your system has getopt_long */
#undef HAVE_GETOPT_LONG

/* Defined if your system has iswgraph of its own*/
#define HAVE_ISWGRAPH

/* Defined if your system has wchar_t of its own */
#define HAVE_WCHAR_T

/* Defined if your system has wint_t of its own */
#define HAVE_WINT_T

#endif // UQM_CONFIG_VC6_H
